sysauto_script.script:
var assetGr = new GlideRecord('x_snc_flowops_asset');
assetGr.addQuery('criticality', 'IN', '1,2');
assetGr.query();

var orchestrator = new FO_AIOrchestrator();

while (assetGr.next()) {
    var assetId = assetGr.getUniqueValue();
    var assetName = assetGr.getValue('asset_name') || 'Unknown Asset';
    var assetType = assetGr.getValue('asset_type') || 'Unknown Type';
    var lastService = assetGr.getValue('last_service_date') || 'Unknown';
    var warranty = assetGr.getValue('warranty_expire') || 'Unknown';
    var criticality = assetGr.getValue('criticality') || 'Unknown';

    var payload = {
        context: {
            task: "Do not summarize the data. Generate a detailed, step-by-step preventative maintenance checklist for this specific asset.",
            asset_name: assetName,
            asset_type: assetType,
            last_service_date: lastService,
            warranty_expire: warranty,
            criticality: criticality
        }
    };

    var request = new sn_ws.RESTMessageV2('FO_AI_Backend', 'Summary');
    request.setRequestHeader('x-flowops-api-key', gs.getProperty('x_snc_flowops.ai_api_key'));
    request.setRequestHeader('Content-Type', 'application/json');
    request.setRequestBody(JSON.stringify(payload));

    var response = request.execute();
    var httpStatus = response.getStatusCode();
    var responseBody = response.getBody();

    if (httpStatus === 200) {
        var result = JSON.parse(responseBody);

        var woGr = new GlideRecord('x_snc_flowops_work_order');
        woGr.initialize();
        woGr.setValue('issue_category', 'preventative');
        woGr.setValue('priority', assetGr.getValue('criticality'));
        woGr.setValue('asset', assetId);
        woGr.setValue('property', assetGr.getValue('property'));
        woGr.setValue('room', assetGr.getValue('room'));
        woGr.setValue('short_description', 'Preventative Maintenance: ' + assetName);
        woGr.setValue('description', result.summary);
        woGr.setValue('status', 'open');
        woGr.setWorkflow(false);
        var woId = woGr.insert();

        orchestrator.assignMaintenance(woId);
    }
}
